'use strict';

const { describe, it, beforeEach } = require('node:test');
const assert = require('node:assert/strict');
const ShoppingCart = require('../src/cart');

// getTotal is deliberately unrounded, so decimal prices need a tolerance.
function assertClose(actual, expected, epsilon = 1e-9) {
  assert.ok(
    Math.abs(actual - expected) < epsilon,
    `expected ${actual} to be within ${epsilon} of ${expected}`
  );
}

describe('ShoppingCart edge cases', () => {
  let cart;

  beforeEach(() => {
    cart = new ShoppingCart();
  });

  describe('unicode and unusual names', () => {
    for (const name of ['café', '🍎 apple', '日本茶', 'naïve—dash', 'Ω']) {
      it(`adds, merges, and removes an item named ${JSON.stringify(name)}`, () => {
        cart.addItem(name, 2, 1);
        cart.addItem(name, 2, 1);
        assert.deepEqual(cart.items, [{ name, price: 2, quantity: 2 }]);
        cart.removeItem(name);
        assert.equal(cart.getItemCount(), 0);
      });
    }

    it('matches names exactly, so NFC and NFD spellings are separate items', () => {
      const nfc = 'café';
      const nfd = 'café';
      cart.addItem(nfc, 1, 1);
      cart.addItem(nfd, 1, 1);
      assert.equal(cart.getItemCount(), 2);
      assert.throws(() => cart.removeItem('cafe'), /item is not in the cart/);
    });

    it('accepts a 10,000-character name', () => {
      const name = 'x'.repeat(10_000);
      cart.addItem(name, 1, 1);
      cart.removeItem(name);
      assert.equal(cart.getItemCount(), 0);
    });

    for (const name of [' ', '\t', '\n  \r', ' ']) {
      it(`rejects the whitespace-only name ${JSON.stringify(name)}`, () => {
        assert.throws(() => cart.addItem(name, 1, 1), TypeError);
        assert.throws(() => cart.removeItem(name), TypeError);
      });
    }
  });

  describe('numeric boundaries', () => {
    it('accepts Number.MAX_SAFE_INTEGER as a quantity', () => {
      cart.addItem('bulk', 0, Number.MAX_SAFE_INTEGER);
      assert.equal(cart.items[0].quantity, Number.MAX_SAFE_INTEGER);
    });

    it('rejects a quantity one past Number.MAX_SAFE_INTEGER', () => {
      assert.throws(() => cart.addItem('bulk', 0, Number.MAX_SAFE_INTEGER + 1), RangeError);
    });

    it('rejects a merge that would push quantity past Number.MAX_SAFE_INTEGER', () => {
      cart.addItem('bulk', 0, Number.MAX_SAFE_INTEGER);
      assert.throws(() => cart.addItem('bulk', 0, 1), {
        name: 'RangeError',
        message: /would exceed 9007199254740991/,
      });
      assert.equal(cart.items[0].quantity, Number.MAX_SAFE_INTEGER);
    });

    it('treats -0 as a valid zero price', () => {
      cart.addItem('freebie', -0, 3);
      assert.equal(cart.getTotal(), 0);
    });

    it('keeps sub-cent prices without rounding', () => {
      cart.addItem('bolt', 0.001, 3);
      assertClose(cart.getTotal(), 0.003);
    });

    it('returns an unrounded float total for decimal prices', () => {
      cart.addItem('a', 0.1, 1);
      cart.addItem('b', 0.2, 1);
      assertClose(cart.getTotal(), 0.3);
    });

    it('applies a percentage discount to a decimal total', () => {
      cart.addItem('book', 19.99, 3);
      cart.applyDiscount(15);
      assertClose(cart.getTotal(), 50.9745);
    });

    it('accepts a very small positive discount', () => {
      cart.addItem('jacket', 100, 1);
      cart.applyDiscount(Number.EPSILON);
      assert.ok(cart.getTotal() <= 100);
    });
  });

  describe('unexpected input types', () => {
    const oddValues = [
      ['a symbol', Symbol('x'), 'symbol'],
      ['a bigint', 5n, 'bigint'],
      ['an object', {}, 'object'],
      ['an array', [5], 'object'],
      ['a boolean', true, 'boolean'],
      ['a null-prototype object', Object.create(null), 'object'],
      ['a function', () => 5, 'function'],
    ];

    for (const [label, value, typeName] of oddValues) {
      it(`reports ${label} as a TypeError naming its type`, () => {
        const received = new RegExp(`received ${typeName}$`);
        assert.throws(() => cart.addItem(value, 1, 1), { name: 'TypeError', message: received });
        assert.throws(() => cart.addItem('a', value, 1), { name: 'TypeError', message: received });
        assert.throws(() => cart.addItem('a', 1, value), { name: 'TypeError', message: received });
        assert.throws(() => cart.removeItem(value), { name: 'TypeError', message: received });
        assert.throws(() => cart.applyDiscount(value), { name: 'TypeError', message: received });
      });
    }

    it('reports null as "null" rather than "object"', () => {
      assert.throws(() => cart.addItem('a', null, 1), { message: /received null$/ });
    });
  });

  describe('failed calls leave state untouched', () => {
    it('a burst of invalid calls does not change items or discount', () => {
      cart.addItem('apple', 2, 3);
      cart.applyDiscount(10);
      const snapshot = structuredClone({ items: cart.items, discount: cart.discount });

      const invalidCalls = [
        () => cart.addItem('apple', -1, 1),
        () => cart.addItem('apple', 2, 0),
        () => cart.addItem('apple', 2, -1),
        () => cart.addItem('', 2, 1),
        () => cart.removeItem('missing'),
        () => cart.applyDiscount(101),
        () => cart.applyDiscount(-1),
        () => cart.applyDiscount(Number.NaN),
      ];
      for (let round = 0; round < 100; round++) {
        for (const call of invalidCalls) {
          assert.throws(call);
        }
      }

      assert.deepEqual({ items: cart.items, discount: cart.discount }, snapshot);
      assert.equal(cart.getTotal(), 5.4);
    });
  });

  describe('instance isolation', () => {
    it('separate carts do not share items or discounts', () => {
      const other = new ShoppingCart();
      cart.addItem('apple', 10, 1);
      cart.applyDiscount(50);
      other.addItem('banana', 4, 1);

      assert.equal(cart.getTotal(), 5);
      assert.equal(other.getTotal(), 4);
      assert.deepEqual(other.items, [{ name: 'banana', price: 4, quantity: 1 }]);
    });
  });

  describe('stress', () => {
    it('totals 10,000 distinct items correctly', () => {
      const count = 10_000;
      for (let i = 1; i <= count; i++) {
        cart.addItem(`item-${i}`, i, 1);
      }
      assert.equal(cart.getItemCount(), count);
      assert.equal(cart.getTotal(), (count * (count + 1)) / 2);
    });

    it('merges 10,000 repeat adds into a single line item', () => {
      for (let i = 0; i < 10_000; i++) {
        cart.addItem('apple', 1, 1);
      }
      assert.equal(cart.getItemCount(), 1);
      assert.equal(cart.items[0].quantity, 10_000);
    });
  });
});

