'use strict';
const fs = require('node:fs');
const path = require('node:path');
const { spawnSync } = require('node:child_process');

const dir = __dirname;
const fixed = fs.readFileSync(path.join(dir, 'fixed.js'), 'utf8');
const original = fs.readFileSync(path.join(dir, 'original.js'), 'utf8');

function mutate(source, pairs) {
  let out = source;
  for (const [from, to] of pairs) {
    if (!out.includes(from)) throw new Error(`mutation anchor not found: ${from}`);
    out = out.replace(from, to);
  }
  return out;
}

const mutants = [
  ['bug 1', 'no price/quantity validation', mutate(fixed, [[
    "    assertFiniteNumber(price, 'price');\n    if (price < 0) {\n      throw new RangeError(`price must be >= 0, received ${price}`);\n    }\n    assertQuantity(quantity);\n", '']])],
  ['bug 1', 'negative price allowed', mutate(fixed, [['if (price < 0) {', 'if (false) {']])],
  ['bug 1', 'negative quantity allowed', mutate(fixed, [['!Number.isSafeInteger(quantity) || quantity < 1', 'false']])],
  ['bug 2', '= instead of !==', mutate(fixed, [['i.name !== name', 'i.name = name']])],
  ['bug 2', 'missing item ignored', mutate(fixed, [['remaining.length === this.items.length', 'false']])],
  ['bug 3', 'off-by-one <=', mutate(fixed, [[
    'for (const item of this.items) {\n      total += item.price * item.quantity;',
    'for (let i = 0; i <= this.items.length; i++) {\n      const item = this.items[i];\n      total += item.price * item.quantity;']])],
  ['bug 4', 'discount added', mutate(fixed, [['return total - (', 'return total + (']])],
  ['bug 5', 'no range check', mutate(fixed, [['percent < MIN_DISCOUNT_PERCENT || percent > MAX_DISCOUNT_PERCENT', 'false']])],
  ['bug 5', 'no validation at all', mutate(fixed, [["    assertFiniteNumber(percent, 'discount percent');\n", ''], ['percent < MIN_DISCOUNT_PERCENT || percent > MAX_DISCOUNT_PERCENT', 'false']])],
  ['all', 'original file verbatim', original],
];

let ok = true;
for (const [tag, label, source] of mutants) {
  fs.writeFileSync(path.join(dir, 'src', 'cart.js'), source);
  const files = fs.readdirSync(path.join(dir, 'tests')).map(f => path.join('tests', f));
  const run = spawnSync(process.execPath, ['--test', '--test-reporter=tap', ...files], { cwd: dir, encoding: 'utf8' });
  const failed = [...run.stdout.matchAll(/^\s*not ok \d+ - (.+)$/gm)].map(m => m[1]);
  const tagged = tag === 'all' ? [1, 2, 3, 4, 5].map(n => `bug ${n}`) : [tag];
  const missing = tagged.filter(t => !failed.some(name => name.startsWith(`${t}:`)));
  const caught = missing.length === 0;
  ok &&= caught;
  const taggedFailCount = failed.filter(n => /^bug \d:/.test(n)).length;
  console.log(`${caught ? 'CAUGHT' : 'MISSED'}  [${tag}] ${label}: ${failed.length} failing tests (${taggedFailCount} bug-tagged)${missing.length ? ` — no failing test for ${missing.join(', ')}` : ''}`);
}
fs.writeFileSync(path.join(dir, 'src', 'cart.js'), fixed);
const clean = spawnSync(process.execPath, ['--test', ...fs.readdirSync(path.join(dir, 'tests')).map(f => path.join('tests', f))], { cwd: dir, encoding: 'utf8' });
console.log(`fixed file: exit ${clean.status}`);
process.exit(ok && clean.status === 0 ? 0 : 1);
EOF
node "$TMP/mutate.js"

